479	
480		if vmi.Status.MigrationState == nil {
481			return true, nil
482		} else if vmi.Status.MigrationState.MigrationUID == migration.UID {
483			return true, nil
484		} else if vmi.Status.MigrationState.MigrationUID == "" {
485			return true, nil
486		}
487	
488		curMigrationUID := vmi.Status.MigrationState.MigrationUID
489	
490		// check to see if the curMigrationUID still exists or is finalized
491		objs, err := c.migrationIndexer.ByIndex(cache.NamespaceIndex, migration.Namespace)
492	
493		if err != nil {
494			return false, err
495		}
496		for _, obj := range objs {
497			curMigration := obj.(*virtv1.VirtualMachineInstanceMigration)
498			if curMigration.UID != curMigrationUID {
499				continue
500			}
501	
502			if curMigration.IsFinal() {
503				// If the other job already completed, it's okay to take over the migration.
504				return true, nil
505			}
506			return false, nil
507		}
508	
509		return true, nil
510	}
