import (
	"testing"

	v1 "kubevirt.io/api/core/v1"
	"kubevirt.io/kubevirt/pkg/pointer"
	"k8s.io/apimachinery/pkg/types"
)

func TestZMigrationProxyKey(t *testing.T) {
	srcUID := types.UID("source-uid")
	base := func() *v1.VirtualMachineInstance {
		vmi := &v1.VirtualMachineInstance{}
		vmi.UID = "local-uid"
		vmi.Annotations = map[string]string{v1.CreateMigrationTarget: "true"}
		vmi.Status.MigrationTransport = v1.MigrationTransportUnix
		vmi.Status.MigrationState = &v1.VirtualMachineInstanceMigrationState{
			SourceState: &v1.VirtualMachineInstanceMigrationSourceState{
				VirtualMachineInstanceUID: pointer.P(srcUID),
			},
		}
		return vmi
	}

	if got := migrationProxyKey(base()); got != "source-uid" {
		t.Fatalf("decentralized unix: expected source-uid, got %s", got)
	}

	// no annotation
	v := base()
	v.Annotations = nil
	if got := migrationProxyKey(v); got != "local-uid" {
		t.Fatalf("no annotation: expected local-uid, got %s", got)
	}

